ArgonTest.InputSource:
module _

import Argon.Core::*

record MyRecord
    value: String
end

proc moveFirst(a: MyRecord, b: MyRecord): () do
    let mut replacement: MyRecord = a
    replacement := MyRecord {
        value: "3"
    }
    puts replacement.value
    puts b.value
end

proc printTuple(a: MyRecord, b: MyRecord): () do
    puts a.value
    puts b.value
end

proc main(): () do
    let mut tupleValue: (MyRecord, MyRecord) = MyRecord {
        value: "1"
    }, MyRecord {
        value: "2"
    }
    moveFirst tupleValue
    tupleValue := MyRecord {
        value: "3"
    }, MyRecord {
        value: "4"
    }
    printTuple tupleValue
end
